fn parse_exec_parts(exec: &str) -> Vec<String> {
    // Very simplified: split by spaces respecting single and double quotes
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    for ch in exec.chars() {
        if escaped {
            current.push(ch);
            escaped = false;
            continue;
        }
        if ch == '\\' && !in_single {
            escaped = true;
            continue;
        }
        if ch == '\'' && !in_double {
            in_single = !in_single;
            continue;
        }
        if ch == '"' && !in_single {
            in_double = !in_double;
            continue;
        }
        if ch == ' ' && !in_single && !in_double {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
            continue;
        }
        current.push(ch);
    }
    if !current.is_empty() {
        parts.push(current);
    }
    parts
}

fn exec_handler(entry: &DesktopEntry, files: &[String]) -> Result<(), String> {
    let exec = &entry.exec;
    let parts = parse_exec_parts(exec);
    // Determine if we need to handle field codes specially for grouping vs separating
    // For launch, we group; for open, we may need to separate per file if %f/%u and multiple files
    // This function is called per handler invocation; for open with multiple files needing separation, caller will call per file
    // So here we just prepare command

    // Replace field codes: we already handled in expand_exec, but need to handle more precisely
    let mut cmd_parts = Vec::new();
    let mut has_field = false;
    for part in parts {
        if part == "%f" || part == "%F" || part == "%u" || part == "%U" {
            has_field = true;
            // For multiple, we will expand later
            // For now, we'll treat as placeholder to be replaced with files
            // We'll just not push placeholder, files will be appended
        } else if part == "%i" || part == "%c" || part == "%k" || part == "%%" {
            if part == "%%" {
                cmd_parts.push("%".to_string());
            }
            // skip others
        } else {
            cmd_parts.push(part);
        }
    }
    if !has_field {
        // Append files
        cmd_parts.extend(files.iter().cloned());
    } else {
        cmd_parts.extend(files.iter().cloned());
    }
    if cmd_parts.is_empty() {
        return Err("No command".to_string());
    }
    let prog = &cmd_parts[0];
    let args = &cmd_parts[1..];
    // Try to execute
    let status = Command::new(prog).args(args).status();
    match status {
        Ok(s) => {
            if s.success() {
                Ok(())
            } else {
                // Even if non-zero, consider success? Original just launches and doesn't check exit?
                Ok(())
            }
        }
        Err(e) => {
            // Original error for NotFound: Io(Os { code: 2, kind: NotFound, message: "No such file or directory" })
            // This happens when handler executable not found or handler not found?
            // For launch/open with handler not found, original prints that error
            // For exec failure (binary not found), it also prints same?
            // We'll return error to be printed as "Error: Io(...)"
            Err(format!("Io(Os {{ code: 2, kind: NotFound, message: \"{}\" }})", e))
        }
    }
}

