fn write_mimeapps(path: &Path, map: &HashMap<String, Vec<String>>) {
    let mut content = String::new();
    content.push_str("[Added Associations]\n\n");
    content.push_str("[Default Applications]\n");
    // Sort keys for deterministic output? Original seems to output in some order - let's check earlier outputs: they were sorted? Earlier we had text/* then text/plain then x-scheme etc alphabetical?
    // Example: after set, file had text/plain=nvim.desktop;\n and also [Added Associations] empty
    // For multiple entries, they were alphabetical? Let's check: after adding handlers, file had text/plain=app1.desktop;app2.desktop; etc but with wildcard, order was text/*, text/plain, etc - maybe sorted alphabetical?
    // Let's sort keys
    let mut keys: Vec<&String> = map.keys().collect();
    keys.sort();
    for k in keys {
        if let Some(v) = map.get(k) {
            if v.is_empty() {
                continue;
            }
            content.push_str(&format!("{}={};\n", k, v.join(";")));
