fn get_desktop_files() -> HashMap<String, DesktopEntry> {
    let mut map = HashMap::new();
    let mut search_paths: Vec<PathBuf> = Vec::new();
    // XDG_DATA_HOME applications
    search_paths.push(get_data_home().join("applications"));
    // XDG_DATA_DIRS
    for dir in get_data_dirs() {
        search_paths.push(dir.join("applications"));
    }
    // Also data_dir via dirs crate may include HOME/.local/share already, but we added
    // Also add fallback for HOME/.local/share if not already
    if let Ok(home) = env::var("HOME") {
        search_paths.push(PathBuf::from(home).join(".local/share/applications"));
    }
    // Also /usr/share/applications
    search_paths.push(PathBuf::from("/usr/share/applications"));

    let mut seen = std::collections::HashSet::new();
    for dir in search_paths {
        if seen.contains(&dir) {
            continue;
        }
        seen.insert(dir.clone());
        if let Ok(entries) = fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().map(|e| e == "desktop").unwrap_or(false) {
                    if let Some(name) = path.file_name().map(|n| n.to_string_lossy().to_string()) {
                        if map.contains_key(&name) {
                            continue;
                        }
                        if let Ok(entry) = parse_desktop_file(&path) {
                            map.insert(name, entry);
                        }
                    }
                }
            }
        }
    }
    map
}

#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    mime_types: Vec<String>,
    no_display: bool,
    path: PathBuf,
}

fn parse_desktop_file(path: &Path) -> Result<DesktopEntry, String> {
    let content = fs::read_to_string(path).map_err(|e| e.to_string())?;
    let mut name = String::new();
    let mut exec = String::new();
    let mut mime_types = Vec::new();
    let mut no_display = false;
    let mut in_desktop = false;
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_desktop = line == "[Desktop Entry]";
            continue;
        }
        if !in_desktop {
            continue;
        }
        if line.starts_with("Name=") {
            name = line["Name=".len()..].to_string();
        } else if line.starts_with("Exec=") {
            exec = line["Exec=".len()..].to_string();
        } else if line.starts_with("MimeType=") {
            let mime_str = &line["MimeType=".len()..];
            mime_types = mime_str.split(';').filter(|s| !s.is_empty()).map(|s| s.trim().to_string()).collect();
        } else if line.starts_with("NoDisplay=") {
            let val = &line["NoDisplay=".len()..];
            no_display = val.trim().to_lowercase() == "true";
        }
    }
    if exec.is_empty() {
        return Err("No Exec".to_string());
    }
    if name.is_empty() {
        // fallback to file name without extension?
        name = path.file_stem().unwrap_or_default().to_string_lossy().to_string();
    }
    Ok(DesktopEntry { name, exec, mime_types, no_display, path: path.to_path_buf() })
}

