    let has_lower = exec_parts.iter().any(|p| p == "%f" || p == "%u");

    // Remove field codes from parts and track
    let mut base_parts: Vec<String> = Vec::new();
    let mut field_type = None; // Some("F") etc
    for part in exec_parts {
        if part == "%f" || part == "%F" || part == "%u" || part == "%U" {
