        } else if part == "%i" || part == "%c" || part == "%k" {
            // These are replaced with empty or icon etc - for handlr, likely ignore
            // For simplicity, skip
        } else {
            base_parts.push(part);
        }
    }
    if field_type.is_none() {
        // No field code, append files
